sql.where:

r.question_type >= 4

    and r.user_id = #{query.userId}


    and q.grade = #{query.grade}


    and kp.subject = #{query.subject}


    and r.question_type = #{query.questionType}


    and r.source = #{query.source}


    and r.review_status = #{query.reviewStatus}


    and (u.username like concat('%', #{query.studentFuzzy}, '%')
        or u.nick_name like concat('%', #{query.studentFuzzy}, '%')
        or u.email like concat('%', #{query.studentFuzzy}, '%'))

mapper.select:
SELECT r.record_id, r.user_id, u.username, u.nick_name, u.grade, r.question_id, q.title AS question_title, q.question_type, q.score AS question_max_score, q.answer AS correct_answer, q.analysis, kp.name AS knowledge_point_name, kp.subject, r.user_answer, r.score, r.source, r.biz_id, l.lesson_name, r.review_status, r.review_score, r.reviewer_id, r.review_comment, r.review_time, r.create_time FROM practice_record r INNER JOIN question_info q ON q.question_id = r.question_id LEFT JOIN user_info u ON u.user_id = r.user_id LEFT JOIN knowledge_point kp ON kp.knowledge_point_id = r.knowledge_point_id LEFT JOIN course_chapter_lesson l ON l.lesson_id = r.biz_id AND r.source = 3
ORDER BY r.review_status ASC, r.create_time DESC
limit #{query.simplePage.start},#{query.simplePage.end}
